UPDATE rent_goal
SET del_yn = 'Y', modified_date = NOW(), modified_nm = #{modifiedNm}
WHERE user_id = #{userId}
  AND status = 'DRAFT'
  AND del_yn = 'N'

UPDATE rent_goal
SET status = #{status}, modified_date = NOW(), modified_nm = #{modifiedNm}
WHERE goal_id = #{goalId}
  AND del_yn = 'N'
